1  /*
     2   * html.c: a libFuzzer target to test several HTML parser interfaces.
     3   *
     4   * See Copyright for the status of this software.
     5   */
     6
     7  #include <libxml/HTMLparser.h>
     8  #include <libxml/HTMLtree.h>
     9  #include <libxml/catalog.h>
    10  #include "fuzz.h"
    11
    12  int
    13  LLVMFuzzerInitialize(int *argc ATTRIBUTE_UNUSED,
    14                       char ***argv ATTRIBUTE_UNUSED) {
    15      xmlFuzzMemSetup();
    16      xmlInitParser();
    17  #ifdef LIBXML_CATALOG_ENABLED
    18      xmlInitializeCatalog();
    19  #endif
    20      xmlSetGenericErrorFunc(NULL, xmlFuzzErrorFunc);
    21
    22      return 0;
    23  }
    24
    25  int
    26  LLVMFuzzerTestOneInput(const char *data, size_t size) {
    27      static const size_t maxChunkSize = 128;
    28      htmlDocPtr doc;
    29      htmlParserCtxtPtr ctxt;
    30      xmlOutputBufferPtr out;
    31      const char *docBuffer;
    32      size_t maxAlloc, docSize, consumed, chunkSize;
    33      int opts;
    34
    35      xmlFuzzDataInit(data, size);
    36      opts = (int) xmlFuzzReadInt(4);
    37      maxAlloc = xmlFuzzReadInt(4) % (size + 1);
    38
    39      docBuffer = xmlFuzzReadRemaining(&docSize);
    40      if (docBuffer == NULL) {
    41          xmlFuzzDataCleanup();
    42          return(0);
    43      }
    44
    45      /* Pull parser */
    46
    47      xmlFuzzMemSetLimit(maxAlloc);
    48      doc = htmlReadMemory(docBuffer, docSize, NULL, NULL, opts);
    49
    50      /*
    51       * Also test the serializer. Call htmlDocContentDumpOutput with our
    52       * own buffer to avoid encoding the output. The HTML encoding is
    53       * excruciatingly slow (see htmlEntityValueLookup).
    54       */
    55      out = xmlAllocOutputBuffer(NULL);
    56      htmlDocContentDumpOutput(out, doc, NULL);
    57      xmlOutputBufferClose(out);
    58
    59      xmlFreeDoc(doc);
    60
    61      /* Push parser */
    62
    63      xmlFuzzMemSetLimit(maxAlloc);
    64      ctxt = htmlCreatePushParserCtxt(NULL, NULL, NULL, 0, NULL,
    65                                      XML_CHAR_ENCODING_NONE);
    66
    67      if (ctxt != NULL) {
    68          htmlCtxtUseOptions(ctxt, opts);
    69
    70          for (consumed = 0; consumed < docSize; consumed += chunkSize) {
    71              chunkSize = docSize - consumed;
    72              if (chunkSize > maxChunkSize)
    73                  chunkSize = maxChunkSize;
    74              htmlParseChunk(ctxt, docBuffer + consumed, chunkSize, 0);
    75          }
    76
    77          htmlParseChunk(ctxt, NULL, 0, 1);
    78          xmlFreeDoc(ctxt->myDoc);
    79          htmlFreeParserCtxt(ctxt);
    80      }
    81
    82      /* Cleanup */
    83
    84      xmlFuzzMemSetLimit(0);
    85      xmlFuzzDataCleanup();
    86      xmlResetLastError();
    87
    88      return(0);
    89  }
